    xindex = tl.program_id(0) * XBLOCK + tl.arange(0, XBLOCK)[:, None]  # XBLOCK=4..16
    xmask = xindex < xnumel
    _acc = tl.full([XBLOCK, R0_BLOCK], 0, tl.float32)
    for r in tl.range(0, r_numel, R0_BLOCK):
        _acc += compute(load(ptr + r + R*xindex, mask=r_mask & xmask))
    result = tl.sum(_acc, 1)[:, None] / r_numel
    tl.store(out + xindex, result, mask=xmask)  # vector store per CTA

